def find_spanning_tree(n, m, D):
    edges = []
    for _ in range(m):
        u, v = map(int, input().split())
        edges.append((u, v))
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(u, v):
        root_u, root_v = find(u), find(v)
        if root_u == root_v:
            return False
        if rank[root_u] > rank[root_v]:
            parent[root_v] = root_u
        elif rank[root_u] < rank[root_v]:
            parent[root_u] = root_v
        else:
            parent[root_v] = root_u
            rank[root_u] += 1
        return True
    spanning_tree = []
    for u, v in edges:
        if union(u, v):
            spanning_tree.append((u, v))
    if find(1) != find(n):
        print("NO")
        return
    degree_of_1 = sum(1 for u, v in spanning_tree if 1 in (u, v))
    if degree_of_1 == D:
        print("YES")
        for u, v in sorted(spanning_tree, key=lambda x: x[0] if x[0] < x[1] else x[1]):
            print(u, v)
    elif degree_of_1 > D:
        print("NO")

