import sys
from collections import defaultdict, deque

def main():
    n, m, D = map(int, input().split())
    graph = [[] for _ in range(n)]
    adj = [defaultdict(int) for _ in range(n)]

    for _ in range(m):
        u, v = map(int, input().split())
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    visited = set()
    queue = deque([(0, 0)])
    parent = [-1]*n
    edges = []

    while queue:
        u, p = queue.popleft()

        if u in visited:
            continue

        visited.add(u)
        parent[u] = p

        for v in graph[u]:
            if v not in visited and adj[p][v] == 0:
                adj[p][v] += 1
                adj[v][p] += 1
                queue.append((v, u))

    if D > len(graph[0]):
        print("NO")
        return

    for i in range(1, n):
        if parent[i] != -1 and adj[parent[i]][i] == 0:
            edges.append((parent[i], i))
            adj[parent[i]][i] += 1
            adj[i][parent[i]] += 1

    while len(edges) < n-1:
        for u in range(n):
            if parent[u] != -1 and adj[parent[u]][u] == 0:
                v = next((v for v in graph[u] if v not in visited), None)
                if v is not None:
                    edges.append((parent[u], u))
                    edges.append((u, v))
                    adj[parent[u]][u] += 1
                    adj[u][parent[u]] += 1
                    adj[u][v] += 1
                    adj[v][u] += 1

    if parent[0] != -1 and len(graph[0]) == D:
        print("YES")
        for u, v in edges:
            print(u+1, v+1)
    else:
        print("NO")

if __name__ == "__main__":
    main()
