def solve():
    n, k = map(int, input().split())
    a = list(map(int, input().split()))
    s = [0] * (n + 1)
    for i in range(n):
        s[i + 1] = s[i] ^ ((a[i] & 1) != 0)

    if k > n - s[-1]:
        print("NO")
        return

    ans = []
    l, r = 0, n
    while k:
        if s[r] == s[l + 1]:
            ans.append(r)
            r -= 1
            k -= 1
        else:
            for i in range(l + 1, r):
                if s[i] ^ s[l + 1] == 1:
                    l = i
                    break
            ans.append(l + 1)
            l += 1
            k -= 1

    print("YES")
    print(*ans)

for _ in range(int(input())):
    solve()

