def f(n, m, a):
    s = sum(a)
    if s < m: return -1
    a.sort(reverse=True)
    d = 0
    for i in range(n):
        s -= a[i]
        d += 1
        if s <= m: break
    else:
        return -1
    return max(d, (m + n - 1) // n)

