    a.sort()
    c = [-1] * n
    used = set()
    for i, x in enumerate(a):
        if not used:
            c[i] = 1
            used.add(x)
        else:
            for j in range(2, k + 1):
                if x not in used and len(used) < j - 1:
                    c[i] = j
                    used.add(x)
                    break
    print('YES')
