def num_to_words(n):
    if n < 10:
        return ["one", "two", "three", "four", "five", "six", "seven", "eight", "nine"][n-1]
    elif n < 20:
        return ["eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"][n-11]
    else:
        tens = (n // 10) * 10
        ones = n % 10
        if ones == 0:
            return ["twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"][tens//20-2]
        else:
            return num_to_words(tens) + num_to_words(ones)

def words_to_num(s):
    ones = {"one": 1, "two": 2, "three": 3, "four": 4, "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9}
    teens = {"eleven": 11, "twelve": 12, "thirteen": 13, "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17, "eighteen": 18, "nineteen": 19}
    tens = {"twenty": 20, "thirty": 30, "forty": 40, "fifty": 50, "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90}
    words = s.split()
    num = 0
    i = 0
    while i < len(words):
        if words[i] == "$":
            break
        elif words[i] in ones:
            num += ones[words[i]]
        elif words[i] in teens:
            num += teens[words[i]]
        elif words[i] in tens:
            num += tens[words[i]]
        i += 1
    return num

def solve():
    n = int(input())
    words = []
    for _ in range(n):
        word = input()
        if word == "$":
            continue
        words.append(word)
    num = words_to_num(" ".join(words))
    words.remove("$")
    words.insert(0, num_to_words(num))
    print(" ".join(words))

