def f(n, c):
    c.sort(reverse=True)
    s = sum(c)
    if s < n: return "impossible"
    l = 0
    r = 1
    while r <= n:
        m = (l + r) // 2
        v = min(m * i for i in range(1, n+1))
        if v >= s:
            r = m + 1
        else:
            l = m - 1
    return str((s - l * n) / s)

