def f(n, k, c, f, h):
    cnt = [0] * 100001
    for i in range(k * n): cnt[c[i]] += 1
    for i in range(1, 100001): cnt[i] += cnt[i - 1]
    dp = [[-float('inf')] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(n):
        for j in range(k + 1):
            if dp[i][j] == -float('inf'): continue
            l, r = max(0, cnt[f[i]] - k), min(cnt[f[i]], k)
            for t in range(l, r + 1):
                dp[i + 1][max(j - t, 0)] = max(dp[i + 1][max(j - t, 0)], dp[i][j] + h[t])
    return max(max(row) for row in dp)

