    dp[i][0] = c[i - 1]

for j in range(1, m + 1):
    for i in range(1, s + 1):
        if c[i - 1] == d:
            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
        else:
            dp[i][j] = max(dp[i - 1][j], min(d - c[i - 1], dp[i][j - 1]) + 1)

if dp[s][m] < m:
    print("impossible")
else:
    ans = [0] * s
    for i in range(s, 0, -1):
        if dp[i][m] > dp[i - 1][m]:
            ans[i - 1] = min(d - c[i - 1], dp[i][m] - dp[i - 1][m])
            m -= (dp[i][m] - dp[i - 1][m])
    print(*ans)
