from collections import deque, defaultdict
import sys

MOD = 1000000007

def solve():
    n = int(input())
    costs = list(map(int, input().split()))
    m = int(input())

    graph = [[] for _ in range(n)]
    for _ in range(m):
        u, v = map(int, input().split())
        graph[u-1].append(v-1)

    visited = [False] * n
    queue = deque()
    for i in range(n):
        if not visited[i]:
            queue.append(i)
            visited[i] = True

            while queue:
                node = queue.popleft()

                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)

    dp = [0] * n
    ways = [1] * n
    for i in range(n):
        if visited[i]:
            dp[i] = costs[i]
            ways[i] = 1

    for i in range(n):
        if not visited[i]:
            continue

        stack = [(i, costs[i])]
        while stack:
            node, cost = stack.pop()

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    continue
                if dp[neighbor] > cost + costs[neighbor]:
                    dp[neighbor] = cost + costs[neighbor]
                    ways[neighbor] = 0

                elif dp[neighbor] == cost + costs[neighbor]:
                    ways[neighbor] += ways[node]

                stack.append((neighbor, cost))

    min_cost = min(dp)
    ans = sum(ways[i] for i in range(n) if dp[i] == min_cost)

    print(min_cost, ans % MOD)

solve()
