def dist(p, q):
    return ((p[0] - q[0]) ** 2 + (p[1] - q[1]) ** 2) ** 0.5

n = int(input())
x = []
y = []
for i in range(n):
    xi, yi = map(float, input().split())
    x.append(xi)
    y.append(yi)

def orientation(p, q, r):
    val = (q[1] - p[1]) * (r[0] - q[0]) - (q[0] - p[0]) * (r[1] - q[1])
    if val == 0:
        return 0
    elif val > 0:
        return 1
    else:
        return 2

def convex_hull(x, y):
    n = len(x)
    if n < 3:
        return []
    hull = []
    l = 0
    for i in range(1, n):
        if x[i] < x[l]:
            l = i
    p = l
    while True:
        hull.append([x[p], y[p]])
        q = (p + 1) % n
        for i in range(n):
            if orientation(hull[-1], [x[q], y[q]], [x[i], y[i]]) == 2:
                q = i
        p = q
        if p == l:
            break
    return hull

def max_dist(x, y):
    n = len(x)
    ch = convex_hull(x, y)
    n = len(ch)
    max_d = 0.0
    for i in range(n - 1):
        d = dist(ch[i], ch[i + 1])
        max_d = min(max_d, d)
    return max_d

