grid = [[0] * W for _ in range(H)]
colors = [i + 1 for i in range(N)]

for i in range(N):
    for j in range(a[i]):
        x, y = divmod(i, W)
        grid[x][y] = colors[i]

for i in range(H):
    for j in range(W):
        if grid[i][j] == 0:
            color = colors.pop()
            queue = deque([(i, j)])
            grid[i][j] = color
            while queue:
                x, y = queue.popleft()
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] == 0:
                        grid[nx][ny] = color
                        queue.append((nx, ny))

for row in grid:
