import sys
from collections import deque

def solve():
    n, m, p = map(int, input().split())
    board = [list(map(int, input().split())) for _ in range(n)]
    moves = []
    queue = deque([(0, 0)])
    visited = set((0, 0))
    while queue:
        x, y = queue.popleft()
        if board[x][y] == p:
            continue
        target = (p - board[x][y]) % p + 1
        for i in range(n):
            for j in range(m):
                if board[i][j] == target and (i, j) not in visited:
                    queue.append((i, j))
                    visited.add((i, j))
        moves.append(target)
    if len(visited) != n * m:
        print(-1)
        return
    moves = moves[::-1]
    for i in range(n):
        for j in range(m):
            board[i][j] = 0
    for move in moves:
        for i in range(n):
            for j in range(m):
                if board[i][j] == 0:
                    board[i][j] += 1
                    if board[i][j] == p:
                        board[i][j] = 1
                    queue.append((i, j))
                    visited.add((i, j))
        while queue:
            x, y = queue.popleft()
            for i in range(n):
                for j in range(m):
                    if (board[i][j] != p and (i, j) not in visited) or board[x][y] == 1:
                        continue
                    board[i][j] += 1
                    if board[i][j] == p:
                        board[i][j] = 1
