    bottles = []
    for _ in range(n):
        xi, yi = map(int, input().split())
        bottles.append((xi, yi))
    bottles.sort(key=lambda x: (x[0] - ax) ** 2 + (x[1] - ay) ** 2)
    bottles.sort(key=lambda x: (x[0] - bx) ** 2 + (x[1] - by) ** 2)

