    bera = defaultdict(int)
    for i, (xi, yi) in enumerate(bottles):
        if i % 2 == 0:
            adil[(xi, yi)] = dist(ax, ay, xi, yi) + dist(xi, yi, tx, ty)
        else:
            bera[(xi, yi)] = dist(bx, by, xi, yi) + dist(xi, yi, tx, ty)

    ans = 0
    for i in range(n):
