def collide(m1, v1, m2, v2):
    return (m1 + m2, (v1[0] + v2[0]) // 2, (v1[1] + v2[1]) // 2, (v1[2] + v2[2]) // 2)

def main():
    n, nx, ny, nz = map(int, input().split())
