    for _ in range(n):
        m, x, y, z, vx, vy, vz = map(int, input().split())
        planetoids.append((m, (x, y, z), (vx, vy, vz)))
    last_collision_time = 0
    while True:
        new_planetoids = []
        collisions = {}
        for i in range(n):
            x, y, z = get_next_location(*planetoids[i][1], *planetoids[i][2], nx, ny, nz)
            for j in range(i + 1, n):
                u, v, w = get_next_location(*planetoids[j][1], *planetoids[j][2], nx, ny, nz)
                if (x, y, z) == (u, v, w):
                    collisions[(i, j)] = collide(planetoids[i][0], planetoids[i][2], planetoids[j][0], planetoids[j][2])
