def orientation(p, q, r):
    return (q[1] - p[1]) * (r[0] - q[0]) > (r[1] - q[1]) * (q[0] - p[0])

def convex_hull(points):
    n = len(points)
    if n < 3:
        return points
    hull = []
    l = 0
    for i in range(1, n):
        if points[i][0] < points[l][0]:
            l = i
    p = l
    q = 0
    while True:
        hull.append(points[p])
        q = (p + 1) % n
        for i in range(n):
            if orientation(points[p], points[i], points[q]) == 0 or points[i][0] < points[p][0]:
                q = i
        p = q
        if p == l:
            break
    return hull

